import sys

MOD = 10**9 + 7

def solve(n, s):
    stack = []
    for i in range(n):
        if s[i] == ')':
            temp = 0
            while stack[-1] != '(':
                temp += stack.pop()
                stack.pop()
            stack.pop()
            if not stack or stack[-1] == '(':
                stack.append(temp % MOD)
            else:
                stack[-1] = (stack[-1] + temp * stack[-1]) % MOD
        elif s[i] != '(':
            stack.append(int(s[i]))
        else:
            stack.append(s[i])
    return sum(stack) % MOD

