    dp = [[0]*n for _ in range(n)]
    for length in range(2, n+1):
        for i in range(n-length+1):
            j = i+length-1
            if s[i+1:j] == s[i+1:j][::-1]:
                dp[i][j] = min(dp[i][k]+dp[k+1][j]+1 for k in range(i, j))
            else:
                dp[i][j] = min(dp[i][k]+dp[k+1][j] for k in range(i, j))
    return dp[0][n-1]

