from collections import defaultdict

def min_colors(graph):
    color = {}
    for node in sorted(graph, key=lambda x: len(graph[x])):
        colors = set(range(len(graph)))
        for i in graph[node]:
            if i in color:
                colors.discard(color[i])
        color[node] = colors.pop()
    return max(color.values) + 1

def main():
    n = int(input().strip())
    graph = defaultdict(set)
    for i in range(n):
        line = list(map(int, input().strip().split()))
        for j in line[1:]:
            graph[i].add(j)
            graph[j].add(i)
    print(min_colors(graph))

if __name__ == "__main__":
    main()

