import sys

def solve():
    N = int(sys.stdin.readline())
    offers = []
    for _ in range(N):
        C, A, B = sys.stdin.readline().split()
        offers.append((int(A), int(B), C))
    offers.sort()

    dp = [[[0]*10001 for _ in range(4)] for _ in range(3)]
    dp[0][0][0] = 1

    for i in range(N):
        for j in range(3):
            for k in range(10001):
                if dp[i%3][j][k]:
                    dp[(i+1)%3][j][k] = 1
                    if k < offers[i][0]:
                        dp[(i+1)%3][j+1][offers[i][1]] = 1
                    elif k == offers[i][0]:
                        dp[(i+1)%3][j+1][offers[i][1]] = 1
                    elif k > offers[i][1]:
                        dp[(i+1)%3][j][k] = 1

    for i in range(3):
        for j in range(4):
            if dp[N%3][j][10000]:
                return N - i
    return "IMPOSSIBLE"

print(solve())

