    dp = [[[0]*10001 for _ in range(4)] for _ in range(4)]
    dp[0][0][0] = 1
    for i in range(N):
        for j in range(4):
            for k in range(10001):
                if dp[i%4][j][k] == 0:
                    continue
                for l in range(j+1):
                    if k+offers[i][1]-offers[i][0]+1 <= 10000:
                        dp[(i+1)%4][l][k+offers[i][1]-offers[i][0]+1] = 1
    for i in range(4):
        for j in range(10001):
            if dp[(N+1)%4][i][j] == 1:
                return N
    return "IMPOSSIBLE"

