def solve():
    N = int(input().strip())
    offers = []
    for _ in range(N):
        C, A, B = input().strip().split()
        A, B = int(A), int(B)
        offers.append((A, B, C))
    offers.sort(key=lambda x: (x[1], x[0]))  # sort by end time, then start time

    ans = []
    end = 0
    for A, B, C in offers:
        if A > end:
            ans.append((C, A, B))
            end = B

    if len(ans) <= 3:
        print(len(ans))
        for C, A, B in ans:
            print(C, A, B)
    else:
        print("IMPOSSIBLE")

