import sys

def solve():
    N = int(sys.stdin.readline())
    offers = []
    for _ in range(N):
        C, A, B = sys.stdin.readline().split()
        offers.append((int(A), int(B), C))
    offers.sort()

    dp = [[0]*10001 for _ in range(4)]
    dp[0][0] = 1

    for i in range(N):
        for j in range(3, 0, -1):
            for k in range(offers[i][0], offers[i][1]):
                if dp[j-1][k]:
                    dp[j][offers[i][1]] = 1

    for i in range(3):
        if dp[i][10000]:
            return i
    return "IMPOSSIBLE"

print(solve())

def max_factoring_weight(s):
    n = len(s)
    dp = [[0]*n for _ in range(n)]
    for length in range(2, n+1):
        for i in range(n-length+1):
            j = i+length-1
            if length == 2:
                dp[i][j] = 1
            else:
                dp[i][j] = min(dp[i][k] + dp[k+1][j] for k in range(i, j))
            if s[i:j] == s[i:j+1]:
                dp[i][j] = min(dp[i][j], dp[i][j//2]+1)
    return dp[0][n-1]

