def process_input(input_string):
    operations = []
    for line in input_string.split('\n'):
        if line.startswith('D'):
            operations.append(('D', int(line.split()[1])))
        elif line.startswith('I'):
            operations.append(('I', int(line.split()[1]), line.split()[2]))
        elif line.startswith('E'):
            return operations

def compare_programs(program1, program2):
    operations1 = process_input(program1)
    operations2 = process_input(program2)

    if len(operations1) != len(operations2):
        return 1

    for op1, op2 in zip(operations1, operations2):
        if op1[0] != op2[0]:
            return 1
        if op1[0] == 'D':
            if op1[1] != op2[1]:
                return 1
        elif op1[0] == 'I':
            if op1[1] != op2[1] or op1[2] != op2[2]:
                return 1

    return 0

program1 = input().strip()
program2 = input().strip()

print(compare_programs(program1, program2))

def process_input():
    operations1 = []
    operations2 = []
    for line in iter(input, 'E'):
        if line.startswith('I'):
            operations1.append(line.split()[1:])
        elif line.startswith('D'):
            operations1.append(line.split()[1:])
    for line in iter(input, 'E'):
        if line.startswith('I'):
            operations2.append(line.split()[1:])
        elif line.startswith('D'):
            operations2.append(line.split()[1:])
    return operations1, operations2

def compare_operations(operations1, operations2):
    return operations1 == operations2

def main():
    operations1, operations2 = process_input()
    result = compare_operations(operations1, operations2)
    print(int(not result))

if __name__ == "__main__":
    main()

