def max_bling():
    d, b, f, t0, t1, t2 = map(int, input().split())
    dp = [[[0 for _ in range(101)] for _ in range(501)] for _ in range(41)]
    dp[0][0][0] = b

    for i in range(1, d+1):
        for j in range(501):
            for k in range(101):
                dp[i][j][k] = max(dp[i-1][j][k],
                                  (dp[i-1][j-100][k-1] if j>=100 and k>=1 else 0) + 100,
                                  (dp[i-1][j-300][k-3] if j>=300 and k>=3 else 0) + 500)

    return max(dp[d][j][k] for j in range(501) for k in range(101))

