def max_bling():
    d, b, f, t0, t1, t2 = map(int, input().split())
    dp = [[0 for _ in range(101)] for _ in range(41)]
    dp[0][0] = b

    for i in range(1, d+1):
        dp[i][0] = max(dp[i-1][0], dp[i-1][1] if f > 0 else 0)
        for j in range(1, 101):
            dp[i][j] = max(dp[i-1][j-1] if j > 0 else 0,
                           dp[i-1][j-1] + 100 if j > 0 and f > 0 else 0,
                           dp[i-1][j-3] + 500 if j > 2 and f > 0 else 0)
        if i % 3 == 0 and i // 3 <= t0:
            f += 1
        if i % 3 == 0 and i // 3 <= t1:
            f += 1
        if i % 3 == 0 and i // 3 <= t2:
            f += 1

    return max(dp[d])

