import sys
from bisect import bisect_right

def read_input():
    n, k = map(int, sys.stdin.readline().split())
    a = list(map(int, sys.stdin.readline().split()))
    b = list(map(int, sys.stdin.readline().split()))
    return n, k, a, b

def solve(n, k, a, b):
    assistants = sorted(zip(a, b))
    dp = []
    for i in range(n):
        idx = bisect_right(dp, assistants[i][1] + k)
        if idx == len(dp):
            dp.append(assistants[i][1])
        else:
            dp[idx] = assistants[i][1]
    return len(dp)

def main():
    n, k, a, b = read_input()
    print(solve(n, k, a, b))

if __name__ == "__main__":
    main()

