import sys
from math import sqrt

def dist(x1, y1, x2, y2):
    return sqrt((x1 - x2) ** 2 + (y1 - y2) ** 2)

def intersection(x1, y1, x2, y2, x3, y3, x4, y4):
    p = x1 * y2 - y1 * x2
    q = x3 * y4 - y3 * x4
    r = x1 * y4 - y1 * x4
    s = x3 * y2 - y3 * x2

    if (x2 - x1) * (y3 - y1) == (y2 - y1) * (x3 - x1):
        return None

    t = (p * (x3 - x4) - (x1 - x2) * q) / ((x2 - x1) * (y3 - y4) - (y2 - y1) * (x3 - x4))
    u = -((x1 - x2) * r + p * (x3 - x1)) / ((x2 - x1) * (y3 - y4) - (y2 - y1) * (x3 - x4))

    if t < 0 or t > 1 or u < 0 or u > 1:
        return None

    x = x1 + t * (x2 - x1)
    y = y1 + t * (y2 - y1)

    return (x, y)

def main():
    n = int(sys.stdin.readline())
    lamps = []
    for _ in range(n):
        x, y, e = map(int, sys.stdin.readline().split())
        lamps.append((x, y, e))

    min_dist = float('inf')
    for i in range(n):
        for j in range(i + 1, n):
            x1, y1, e1 = lamps[i]
            x2, y2, e2 = lamps[j]
            if e1 * e2 < 0:
                p = intersection(x1, y1, x1 + 1, y1, x2, y2, x2 + 1, y2)
                if p is not None:
                    min_dist = min(min_dist, dist(*p, x1, y1) + dist(x2, y2, *p))

    if min_dist == float('inf'):
        print('IMPOSSIBLE')
    else:
        print('{:.7f}'.format(min_dist))

if __name__ == '__main__':
    main()

