from collections import defaultdict

def solve():
    n = int(input().strip())
    lines = [list(map(int, input().strip().split())) for _ in range(n)]

    points = defaultdict(int)
    for line in lines:
        x1, y1, x2, y2 = line
        if x1 == x2:
            for y in range(min(y1, y2), max(y1, y2) + 1):
                points[(x1, y)] += 1
        else:
            for x in range(min(x1, x2), max(x1, x2) + 1):
                points[(x, y1)] += 1

    intersection_points = [point for point, count in points.items() if count > 1]
    if len(intersection_points) == 0:
        print(-1)
    else:
        print(len(intersection_points))

if __name__ == "__main__":
    solve()

from collections import defaultdict
from sys import stdin

def solve():
    n = int(stdin.readline())
    events = defaultdict(int)
    for _ in range(n):
        x0, y0, x1, y1 = map(int, stdin.readline().split())
        if x1 < x0:
            x0, x1 = x1, x0
        if y1 < y0:
            y0, y1 = y1, y0
        events[(x0, y0)] += 1
        events[(x1, y1)] -= 1

    cur = 0
    ans = 0
    for k in sorted(events.keys()):
        cur += events[k]
        if cur > 1:
            return -1
        if k[0] == k[1] and cur == 1:
            ans += 1
    return ans

print(solve())

