        for j in range(i+1, n):
            x3, y3, x4, y4 = lines[j]
            if (x1-x2)*(y3-y4) == (y1-y2)*(x3-x4):
                if x1 == x2 and x1*(x3-x4) == x3*(x1-x2) and min(y3, y4) <= y1 <= max(y3, y4):
                    points[(x1, y1)] += 1
                elif x3 == x4 and x3*(x1-x2) == x1*(x3-x4) and min(y1, y2) <= y3 <= max(y1, y2):
                    points[(x3, y3)] += 1
                elif (x1, y1) == (x3, y3) or (x1, y1) == (x4, y4) or (x2, y2) == (x3, y3) or (x2, y2) == (x4, y4):
