def count_hill_numbers(n):
    if n < 10:
        return n
    n_str = str(n)
    length = len(n_str)
    dp = [[0]*length for _ in range(length)]
    dp[0][0] = 1
    for i in range(1, length):
        dp[i][i] = dp[i-1][i-1]*10
        for j in range(i-1, -1, -1):
            dp[j][i] = dp[j][i-1] + dp[j+1][i]
            if n_str[j] == n_str[j+1]:
                dp[j][i] += dp[j+1][i-1] + 1
            elif n_str[j] < n_str[j+1]:
                dp[j][i] += dp[j+1][i-1]
            else:
                dp[j][i] = dp[j+1][i]
    return dp[0][length-1]

n = int(input().strip())
