def count_hill_numbers(n):
    # Initialize the dp array
    dp = [[0]*10 for _ in range(19)]
    for i in range(10):
        dp[1][i] = 1

    # Fill the dp array
    for i in range(2, 19):
        for j in range(10):
            dp[i][j] = dp[i-1][j]
            if j > 0:
                dp[i][j] += dp[i-1][j-1]

    # Count the hill numbers
    s = str(n)
    length = len(s)
    res = 0
    prev = 0
    for i in range(1, length):
        res += dp[i][9]

    for i in range(length):
        curr = int(s[i])
        for j in range(prev, curr):
            res += dp[length-i][j]
        if i == length-1 and curr > 0:
            res += 1
        if curr == 0:
            return -1
        prev = curr

    return res

