def count_hill_numbers(n):
    n_str = str(n)
    length = len(n_str)
    dp = [[0]*10 for _ in range(length+1)]
    dp[0][0] = 1
    for i in range(1, 10):
        dp[0][i] = 1
    for i in range(1, length+1):
        for j in range(10):
            dp[i][j] = dp[i-1][j] + dp[i][j-1]
    for i in range(1, length):
        for j in range(int(n_str[i])):
            dp[i+1][j] = 0
        dp[i+1][int(n_str[i])] = dp[i][int(n_str[i])]
        for j in range(int(n_str[i])+1, 10):
            dp[i+1][j] = dp[i+1][j-1]
    return sum(dp[length])

