                if j != (k+1)%3:
                    dp[i+1][j][(k+1)%3] = (dp[i+1][j][(k+1)%3] + dp[i][j][k]) % MOD
                if (j+1)%3 != k:
                    dp[i+1][(j+1)%3][k] = (dp[i+1][(j+1)%3][k] + dp[i][j][k]) % MOD
                if (j+1)%3 != (k+1)%3:
                    dp[(i+1)][(j+1)%3][(k+1)%3] = (dp[(i+1)][(j+1)%3][(k+1)%3] + dp[i][j][k]) % MOD
    res = 0
