    dp = [[[[0, 0] for _ in range(3)] for _ in range(3)] for _ in range(N+1)]
    dp[0][0][0][0] = 1
    for i in range(N):
        for j in range(3):
            for k in range(3):
                for l in range(2):
                    if dp[i][j][k][l] == 0:
                        continue
                    for m in range(3):
                        if m == j:
                            continue
                        dp[i+1][m][(k+1)%3][1] += dp[i][j][k][l]
                        dp[i+1][m][(k+1)%3][1] %= MOD
                    if l == 1:
                        continue
                    for m in range(3):
                        if m == j:
                            continue
                        dp[i+1][m][(k+1)%3][0] += dp[i][j][k][l]
                        dp[i+1][m][(k+1)%3][0] %= MOD
    res = 0
    for j in range(3):
        for k in range(3):
            for l in range(2):
                res += dp[N][j][k][l]
                res %= MOD
    print(res)

