def solve():
    a11, a12, a21, a22, N = map(int, input().split())
    dp = [[[[0, 0] for _ in range(3)] for _ in range(a11+a12+1)] for _ in range(a21+a22+1)]
    dp[a21][a11][0][0] = 1
    for i in range(a21+a22):
        for j in range(a11+a12+1):
            for k in range(3):
                if dp[i][j][k][0] == 0: continue
                if j < a11 + a12:
                    dp[i+1][j+1][(k+1)%3][1] += dp[i][j][k][0]
                    dp[i+1][j+1][(k+1)%3][1] %= MOD
                    dp[i+1][j+1][(k+1)%3][0] += dp[i][j][k][0]
                    dp[i+1][j+1][(k+1)%3][0] %= MOD
                if j > 0:
                    dp[i+1][j-1][(k+2)%3][1] += dp[i][j][k][0]
                    dp[i+1][j-1][(k+2)%3][1] %= MOD
                    dp[i+1][j-1][(k+2)%3][0] += dp[i][j][k][0]
                    dp[i+1][j-1][(k+2)%3][0] %= MOD
    ans = 0
    for j in range(a11+a12+1):
        for k in range(3):
            ans += dp[N][j][k][0] + dp[N][j][k][1]
            ans %= MOD
    print(ans)

solve()

