def solve(n, m, s, t, graph):
    left_heap = [(0, s)]
    right_heap = [(0, s)]
    left_dist = [float('inf')] * n
    right_dist = [float('inf')] * n
    left_dist[s] = 0
    right_dist[s] = 0
    while left_heap or right_heap:
        ld, lnode = heapq.heappop(left_heap) if left_heap else (float('inf'), None)
        rd, rnode = heapq.heappop(right_heap) if right_heap else (float('inf'), None)
        if lnode is not None:
            for v, w in graph[lnode]:
                if ld + w < left_dist[v]:
                    left_dist[v] = ld + w
                    heapq.heappush(left_heap, (left_dist[v], v))
        if rnode is not None:
            for v, w in graph[rnode]:
                if rd + w < right_dist[v]:
                    right_dist[v] = rd + w
                    heapq.heappush(right_heap, (rightt_dist[v], v))
    if left_dist[t] == float('inf') or right_dist[t] == float('inf'):
        return 'infinity'
    return max(left_dist[t], right_dist[t])

