import heapq

def read_input():
    n, m, s, t = map(int, input().split())
    graph = [[] for _ in range(n)]
    for _ in range(m):
        a, b, w = map(int, input().split())
        graph[a].append((b, w))
    return n, m, s, t, graph

def dijkstra(graph, start, end):
    n = len(graph)
    dist = [float('inf')] * n
    dist[start] = 0
    heap = [(0, start)]
    while heap:
        d, node = heapq.heappop(heap)
        if node == end:
            return dist[node]
        if d > dist[node]:
            continue
        for neighbor, w in graph[node]:
            next_dist = d + w
            if next_dist < dist[neighbor]:
                dist[neighbor] = next
                heapq.heappush(heap, (next_dist, neighbor))
    return float('inf')

def main():
    n, m, s, t, graph = read_input()
    result = dijkstra(graph, s, t)
    if result == float('inf'):
        print('infinity')
    else:
        print(result)

if __name__ == "__main__":
    main()

