import heapq

def dijkstra(graph, start, end):
    shortest_distances = {node: [float('infinity'), float('infinity')] for node in graph}
    shortest_distances[start][0] = 0
    heap = [(0, start, 0)]
    while heap:
        dist, current, turn = heapq.heappop(heap)
        if current == end:
            return min(shortest_distances[end])
        for neighbor, weight in graph[current].items():
            old_distance = shortest_distances[neighbor][1 - turn]
            new_distance = shortest_distances[current][turn] + weight
            if new_distance < old_distance:
                shortest_distances[neighbor][1 - turn] = new_distance
                heapq.heappush(heap, (new_distance, neighbor, 1 - turn))
    return float('infinity')

