                new_dist = dist + weight
                if new_dist < right_dist[neighbor]:
                    right_dist[neighbor] = new_dist
                    heapq.heappush(right_heap, (new_dist, neighbor))
        left_turn = not left_turn
    result = min(left_dist[t], right_dist[t])
    if result == float('inf'):
        print('infinity')
