def main():
    n, m, s, t = map(int, input().split())
    graph = [[] for _ in range(n)]
    for _ in range(m):
        a, b, w = map(int, input().split())
        graph[a].append((b, w))

    left_heap = [(0, s, True)]  # time, node, is_left
    right_heap = [(0, s, False)]  # time, node, is_right
    left_visited = [False] * n
    right_visited = [False] * n

    while left_heap or right_heap:
        time, node, is_left = heapq.heappop(left_heap if left_heap else right_heap)
        visited = left_visited if is_left else right_visited
        if visited[node]:
            continue
        visited[node] = True
        if node == t and is_left:
            print(time)
            return

        for neighbor, weight in graph[node]:
            if not visited[neighbor]:
                next_time = time + weight
                if is_left:
                    heapq.heappush(left_heap, (next_time, neighbor, False))
                else:
                    heapq.heappush(right_heap, (next_time, neighbor, True))

    print('infinity')

