import sys

MOD = 10**9 + 7

def solve(n, a, b, c):
    dp = [[0]*82 for _ in range(82)]
    dp[0][0] = 1
    for i in range(1, n+1):
        dp[i] = dp[i-1][:]
        for j in range(i*2, -1, -1):
            for k in range(min(i, j)+1):
                dp[i][j] = (dp[i][j] + dp[i-1][j-k] * a[i-1] * pow(b[i-1], k, MOD)) % MOD
    return sum(dp[n][i] for i in c) % MOD

