def solve():
    n = int(input())
    balls = list(map(int, input().split()))
    no_next = set(map(int, input().split()[1:]))
    fav_seq = list(map(int, input().split()[1:]))

    dp = [[0]*2 for _ in range(n+1)]
    dp[0][0] = 1

    for i in range(n):
        for j in range(2):
            if dp[i][j] == 0:
                continue
            for k in range(1, balls[i]+1):
                if k not in no_next:
                    dp[i+1][j^(k==fav_seq[0])] += dp[i][j]
                    dp[i+1][j^(k==fav_seq[0])] %= MOD

    print(dp[n][0])

