def solve(n, e):
    dp = [[0] * 63 for _ in range(63)]
    dp[0][0] = 1
    for i in range(1, 63):
        dp[i][0] = 2 * dp[i-1][0]
        for j in range(1, i+1):
            dp[i][j] = dp[i-1][j-1] + dp[i-1][j]

    e_str = bin(e)[2:]
    len_e = len(e_str)
    n_str = str(n)
    len_n = len(n_str)
    ans = 0
    prev = 0
    for i in range(len_n):
        digit = int(n_str[i])
        for j in range(len_e):
            if e_str[j] == '1':
                ans += dp[len_n - i - 1][62 - j]
        if digit > 1:
            ans += dp[len_n - i - 1][62]
        if i > 0 and digit == 1:
            ans += prev + 1
        prev = digit * dp[len_n - i - 1][62]
    return ans

