def solve(n, e):
    dp = [[0] * 63 for _ in range(63)]
    dp[0][0] = 1
    for i in range(1, 63):
        dp[i][0] = 2 * dp[i-1][0]
        for j in range(1, i+1):
            dp[i][j] = dp[i-1][j-1] + dp[i-1][j]

    e_str = bin(e)[2:]
    len_e = len(e_str)
    dp2 = [[0] * (len_e+1) for _ in range(63)]
    dp2[0][0] = 1
    for i in range(1, 63):
        dp2[i][0] = 2 * dp2[i-1][0]
        for j in range(1, len_e+1):
            dp2[i][j] = dp2[i-1][j-1] + dp2[i-1][j]

    n_str = str(n)
    len_n = len(n_str)
    ans = 0
    for i in range(len_n):
        for j in range(i+1):
            if j < len_e and n_str[len_n-i-1] > e_str[len_e-j-1]:
                ans += dp[i][j]
                break
            elif j == len_e and n_str[len_n-i-1] > e_str[0]:
                ans += dp[i][j]
                break
            elif j < len_e:
                ans += dp[i][j]
        if i < len_e and n_str[len_n-i-1] > e_str[len_e-i-1]:
            break
        elif i == len_e - 1 and n_str[0] > e_str[0]:
            break

    return ans

