def count_numbers(n, e):
    dp = [[0] * 63 for _ in range(65)]
    dp[0][0] = 1
    for i in range(1, 64):
        dp[i][0] = 2 * dp[i-1][0]
        for j in range(1, 62):
            dp[i][j] = dp[i-1][j-1] + dp[i-1][j]

    digits = []
    while n:
        digits.append(n % 10)
        n //= 10
    digits.reverse()

    cnt = [0] * 62
    for i in range(len(digits)):
        for j in range(62):
            if i > 0 and j > 0:
                cnt[j] += digits[i] * dp[63-i][j-1]
            elif i > 0:
                cnt[j] += digits[i] * dp[63-i][j]
            elif j > 0:
                cnt[j] += dp[63-i][j-1]

    res = 0
    for i in range(62):
        if e == i:
            res += cnt[i] + 1
        elif e < i:
            break
        else:
            res += cnt[i]
    return res

