    dp[0][0] = 1
    for i in range(1, 19):
        dp[i][0] = 1
    for i in range(1, 19):
        for j in range(1, e + 1):
            dp[i][j] = dp[i - 1][j] + dp[i][j - 1]
    res = 0
    s = str(n)
