def count_numbers_with_power_of_2(n, e):
    if e == 0:
        return 1
    res = 0
    for len_power_of_2 in range(1, 65):
        if e <= len_power_of_2 * (len_power_of_2 + 1) // 2:
            res += count_numbers(n, e)
            break
        else:
            res += count_numbers(n, len_power_of_2 * (len_power_of_2 + 1) // 2)
            e -= len_power_of_2 * (len_power_of_2 + 1) // 2
    return res

