import sys
from collections import Counter

def prime_factors(n):
    i = 2
    factors = []
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)
    return set(factors)

def max_revenue():
    n = int(sys.stdin.readline().strip())
    s = list(map(int, sys.stdin.readline().strip().split()))
    total_revenue = 0
    for i in range(n):
        total_revenue += len(prime_factors(s[i]))
    return total_revenue

